package dev.mcpmcp.core;
import com.google.gson.*;
import java.util.*;
public final class Jobs {
 @FunctionalInterface public interface Step {JsonObject tick()throws Exception;}
 public interface Cleanup {void cleanup();}
 private static final class Entry {String id,name;JsonObject args,result;Step step;long epoch,deadline;Entry(String i,String n,JsonObject a,Step s,long e,long timeout){id=i;name=n;args=a.deepCopy();step=s;epoch=e;deadline=System.nanoTime()+timeout*1000000;result=Jsons.obj("action_id",i,"status","queued","queued_at",System.currentTimeMillis());}}
 private final LinkedHashMap<String,Entry> entries=new LinkedHashMap<>();private final Set<String> seen=new HashSet<>();private Entry running;private boolean pumping;
 public synchronized JsonObject submit(String id,String name,JsonObject args,Step step,long epoch,long timeout){if(!id.matches("[A-Za-z0-9_.-]{1,96}")||timeout<1||timeout>300000)return Jsons.error("invalid_job_request");Entry old=entries.get(id);if(old!=null)return old.name.equals(name)&&old.args.equals(args)?old.result.deepCopy():Jsons.error("action_id_conflict");if(seen.contains(id))return Jsons.error("expired_action_id");long active=entries.values().stream().filter(e->e.result.get("status").getAsString().matches("queued|running")).count();if(active>=32||seen.size()>=32768)return Jsons.error("job_capacity_reached");if(entries.size()>=512){var it=entries.values().iterator();while(it.hasNext()){Entry e=it.next();if(!e.result.get("status").getAsString().matches("queued|running")){it.remove();break;}}}Entry e=new Entry(id,name,args,step,epoch,timeout);entries.put(id,e);seen.add(id);return e.result.deepCopy();}
 public synchronized void pump(long epoch){if(pumping)return;pumping=true;try{pumpOnce(epoch);}finally{pumping=false;}}
 private void pumpOnce(long epoch){if(running==null)running=entries.values().stream().filter(e->e.result.get("status").getAsString().equals("queued")).findFirst().orElse(null);Entry e=running;if(e==null)return;if(e.epoch!=epoch){end(e,"cancelled",Jsons.error("world_changed"));return;}if(System.nanoTime()>e.deadline){end(e,"failed",Jsons.error("task_timeout"));return;}e.result.addProperty("status","running");try{JsonObject r=e.step.tick();if(r==null)r=new JsonObject();e.result.add("progress",r.deepCopy());if(Jsons.bool(r,"pending",false))return;end(e,r.has("error")?"failed":(Jsons.bool(r,"observed_success",false)||Jsons.str(r,"status","").equals("observed_success"))?"observed_success":"submitted",r);}catch(Exception|LinkageError ex){end(e,"failed",Jsons.obj("error","action_failed","reason",ex.getClass().getSimpleName()+": "+Objects.toString(ex.getMessage(),"")));}}
 private void end(Entry e,String status,JsonObject result){e.result.addProperty("status",status);e.result.add("result",result);e.result.addProperty("finished_at",System.currentTimeMillis());if(e.step instanceof Cleanup c)try{c.cleanup();}catch(Exception ex){e.result.addProperty("cleanup_error",ex.toString());}e.step=null;if(running==e)running=null;}
 public synchronized JsonObject result(String id){Entry e=entries.get(id);return e==null?Jsons.error("unknown_or_expired_job"):e.result.deepCopy();}
 public synchronized JsonObject cancel(String id){Entry e=entries.get(id);if(e==null)return Jsons.error("unknown_or_expired_job");if(e.step!=null)end(e,"cancelled",Jsons.obj("cancelled",true));return e.result.deepCopy();}
 public synchronized void cancelAll(){for(Entry e:new ArrayList<>(entries.values()))if(e.step!=null)end(e,"cancelled",Jsons.obj("cancelled",true));}
}
